1	package docker
2	
3	import (
4		"context"
5		"fmt"
6		"os/exec"
7		"strings"
8	)
9	
10	// dockerCmd describes one CLI invocation.
11	type dockerCmd struct {
12		// Args are passed to the binary verbatim, e.g. {"ps", "--format", "..."}.
13		Args []string
14		// Stdin is written to the process when non-empty. Used to keep secrets out
15		// of the process list (`docker login --password-stdin`).
16		Stdin string
17		// Combined merges stderr into the returned bytes. Docker writes failure
18		// detail to stderr, so mutating calls set this to produce a usable message;
19		// calls that parse stdout leave it false.
20		Combined bool
21		// Helper runs `docker-credential-<Helper>` instead of `docker`.
22		Helper string
23		// Ctx kills the process when it is cancelled. Nil for the invocations
24		// nobody can stop — which is all of them but the pull, the one long call
25		// this package makes that `K` is offered on (jobs.KindPull.Cancellable).
26		// A nil Ctx builds exactly the command it built before.
27		Ctx context.Context
28	}
29	
30	// dockerRunner is the seam every CLI invocation in this package passes through.
31	//
32	// The package talks to the Docker CLI rather than the SDK, which keeps the
33	// dependency light but makes the whole package untestable without a daemon.
34	// Routing through this interface lets tests exercise the argument building and
35	// output parsing — the parts that actually carry defects — against canned
36	// output.
37	type dockerRunner interface {
38		// LookPath reports whether the docker binary is reachable on PATH.
39		LookPath() error
40		// Run executes one invocation and returns its captured output.
41		Run(cmd dockerCmd) ([]byte, error)
42		// Build returns a ready-to-run command without executing it, for callers
43		// that hand the process to a terminal (tea.ExecProcess).
44		Build(args ...string) *exec.Cmd
45	}
46	
47	// cliRunner is the production dockerRunner: it shells out to the real binary.
48	type cliRunner struct{}
49	
50	func (cliRunner) LookPath() error {
51		_, err := exec.LookPath("docker")
52		return err
53	}
54	
55	func (cliRunner) Build(args ...string) *exec.Cmd {
56		return exec.Command("docker", args...)
57	}
58	
59	func (cliRunner) Run(dc dockerCmd) ([]byte, error) {
60		name := "docker"
61		if dc.Helper != "" {
62			name = "docker-credential-" + dc.Helper
63		}
64		cmd := exec.Command(name, dc.Args...) //nolint:gosec // helper name comes from ~/.docker/config.json
65		if dc.Ctx != nil {
66			cmd = exec.CommandContext(dc.Ctx, name, dc.Args...) //nolint:gosec // same argument as above
67		}
68		if dc.Stdin != "" {
69			cmd.Stdin = strings.NewReader(dc.Stdin)
70		}
71		if dc.Combined {
72			return cmd.CombinedOutput()
73		}
74		return cmd.Output()
75	}
76	
77	// runner is swapped by tests via stubRunner. Production code never reassigns
78	// it, so the package stays safe to call concurrently; tests that swap it must
79	// not run in parallel.
80	var runner dockerRunner = cliRunner{}
81	
82	// requireDocker reports the absence of the docker binary with the error message
83	// callers have always produced.
84	func requireDocker() error {
85		if err := runner.LookPath(); err != nil {
86			return fmt.Errorf("docker not found: %w", err)
87		}
88		return nil
89	}
